  // Remaining high-priority gaps found by the static comparison
  "Couldn't save the Slack app details. Try again before continuing.":
    "Não foi possível salvar os detalhes do aplicativo Slack. Tente novamente antes de continuar.",
  "Couldn't load Slack setup.": "Não foi possível carregar a configuração do Slack.",
  "Uninstall Plugin": "Desinstalar plugin",
  Author: "Autor",
  "Open Environments": "Abrir ambientes",
  "Checking health...": "Verificando saúde…",
  "No saved secret": "Nenhum segredo salvo",
  "Stream run logs": "Transmitir logs da execução",
  "Adds a Conference Room — one chat where you and your whole team work together — plus the live activity feed and the redesigned onboarding. Also restyles task threads as chat bubbles. Turn off anytime to restore the classic UI.":
    "Adiciona uma Sala de conferência — um chat onde você e toda a sua equipe trabalham juntos — além do feed de atividade ao vivo e da integração inicial redesenhada. Também transforma threads de tarefas em balões de chat. Desative a qualquer momento para restaurar a interface clássica.",
  "Treat a project that has no execution workspace policy of its own as if it selected isolated workspaces, so its tasks get a per-task worktree instead of sharing the project checkout. A project that carries its own policy keeps it.":
    "Trate um projeto sem política própria de espaço de trabalho de execução como se tivesse selecionado espaços isolados, para que suas tarefas recebam um worktree por tarefa em vez de compartilharem o checkout do projeto. Um projeto que tenha sua própria política a mantém.",
  "Omitted settings stay unchanged. Instruction file contents, inherited access, and history are available in their settings tabs.":
    "As configurações omitidas permanecem inalteradas. O conteúdo dos arquivos de instruções, o acesso herdado e o histórico estão disponíveis nas respectivas abas de configuração.",
  "Created credentials": "Credenciais criadas",
  "Copy this key now. It won’t be shown again after leaving this page.":
    "Copie esta chave agora. Ela não será exibida novamente depois que você sair desta página.",
  "Changes save in this order. If one fails, earlier changes remain saved.":
    "As alterações são salvas nesta ordem. Se uma falhar, as anteriores continuarão salvas.",
  "Reload saved": "Recarregar salvos",
  "Resolving effective access…": "Resolvendo acesso efetivo…",
  "Browser calls use the signed-in Paperclip user’s current company access. Each call stays bound to its selected agent and task.":
    "As chamadas do navegador usam o acesso atual da empresa do usuário conectado ao Paperclip. Cada chamada permanece vinculada ao agente e à tarefa selecionados.",
  "Outgoing calls use your saved callback number and opt-in. For a private incoming call, enter the code spoken on the phone in signed-in Paperclip and select a task to approve that live call. Incoming calls can start a new conversation task without sign-in, under a task-scoped low-trust policy. Private mode is optional and requires approval before accessing existing tasks.":
    "As chamadas realizadas usam seu número de callback salvo e sua autorização. Para uma chamada recebida privada, digite no Paperclip conectado o código falado ao telefone e selecione uma tarefa para aprovar a chamada ao vivo. Chamadas recebidas podem iniciar uma nova tarefa de conversa sem login, sob uma política de baixa confiança no escopo da tarefa. O modo privado é opcional e exige aprovação antes de acessar tarefas existentes.",
  Send: "Enviar",
