  "Enter the requested credentials below. Other saved credentials stay in place.": "Informe abaixo as credenciais solicitadas. As outras credenciais salvas permanecem.",
  "The numeric App ID on the GitHub App’s settings page. This is different from its Client ID or installation ID.": "O ID numérico do aplicativo na página de configurações do GitHub App. Ele é diferente do ID do cliente ou do ID de instalação.",
