  "Private key": "Chave privada",
  "Upload the .pem file downloaded from this GitHub App, or paste its entire contents, including the BEGIN and END lines.": "Envie o arquivo .pem baixado deste aplicativo GitHub ou cole todo o seu conteúdo, incluindo as linhas BEGIN e END.",
  "In the same App’s settings, open": "Nas configurações do mesmo aplicativo, abra",
  "You can reuse a .pem file you already saved. GitHub cannot show an old private key again. Creating a new key for the same App keeps its installation.": "Você pode reutilizar um arquivo .pem já salvo. O GitHub não pode exibir uma chave privada antiga novamente. Criar uma nova chave para o mesmo aplicativo mantém a instalação.",
  "Private key loaded. Paste or upload another key to replace it.": "Chave privada carregada. Cole ou envie outra chave para substituí-la.",
  "Use a PEM private key, including its BEGIN and END lines. A token or client secret won’t work here.": "Use uma chave privada PEM, incluindo as linhas BEGIN e END. Um token ou segredo do cliente não funcionará aqui.",
  "The secret configured for this App’s webhook. It must match GitHub exactly.": "O segredo configurado para o webhook deste aplicativo. Ele deve corresponder exatamente ao GitHub.",
  "Use the secret saved when you configured this App’s webhook. If you no longer have it, change the webhook secret in GitHub App settings and enter the same value here.": "Use o segredo salvo quando configurou o webhook deste aplicativo. Se não o tiver mais, altere o segredo do webhook nas configurações do GitHub App e informe o mesmo valor aqui.",
