  // Chat endpoint detail provider instructions
  "Reverify this voice persona and update its signed session tools. Existing task assignments stay attached to their history.": "Verifique novamente esta persona de voz e atualize as ferramentas da sessão assinada. As atribuições de tarefas existentes continuam vinculadas ao histórico.",
  "Stop this connection from accepting voice requests. Accepted work and task history remain in Paperclip.": "Impeça esta conexão de aceitar solicitações de voz. O trabalho aceito e o histórico de tarefas permanecem no Paperclip.",
  "Reconnect verifies or replaces credentials for this same Slack app. It does not reinstall the app or change its workspace or channel membership.": "Reconectar verifica ou substitui as credenciais deste mesmo aplicativo do Slack. Isso não reinstala o aplicativo nem altera seu workspace ou os canais dos quais participa.",
  "Paperclip archives the endpoint, stops new ingress, and retires its saved Slack credentials. It does not uninstall the Slack app: the app remains installed, and its bot remains in channels, until you remove them in Slack.": "O Paperclip arquiva o endpoint, interrompe novas entradas e desativa as credenciais salvas do Slack. Isso não desinstala o aplicativo do Slack: o aplicativo continua instalado e o bot permanece nos canais até que você os remova no Slack.",
  "Reconnect verifies this same App and installation, then updates its webhook URL, secret, and secure delivery settings. It does not reinstall the App or change repository access.": "Reconectar verifica este mesmo aplicativo e instalação e atualiza sua URL de webhook, segredo e configurações de entrega segura. Isso não reinstala o aplicativo nem altera o acesso aos repositórios.",
  "Reconnect verifies this same Discord application and server installation. It does not add or remove the bot from the server.": "Reconectar verifica este mesmo aplicativo do Discord e sua instalação no servidor. Isso não adiciona nem remove o bot do servidor.",
  "Reconnect verifies this same Microsoft app, tenant, and bot identity. It does not upload or reinstall the Teams app.": "Reconectar verifica este mesmo aplicativo da Microsoft, tenant e identidade do bot. Isso não envia nem reinstala o aplicativo do Teams.",
  "Reconnect verifies the same Photon project and line allocation, then recovers eligible missed messages.": "Reconectar verifica o mesmo projeto Photon e a alocação da linha e recupera as mensagens perdidas elegíveis.",
  "Disconnect archives this channel and removes its saved secret. Your Photon project, number, subscription, and Messages history remain in Photon.": "Desconectar arquiva este canal e remove seu segredo salvo. Seu projeto Photon, número, assinatura e histórico do Messages permanecem no Photon.",
  "Reconnect verifies the same BotFather bot and automatically refreshes its Paperclip webhook and command menu.": "Reconectar verifica o mesmo bot do BotFather e atualiza automaticamente o webhook do Paperclip e o menu de comandos.",
  "The file upload was confirmed, but its Teams notification was not. Check Teams first. Retrying sends only that notification, not the file bytes, and may create a duplicate card.": "O envio do arquivo foi confirmado, mas a notificação do Teams não. Verifique o Teams primeiro. Tentar novamente envia apenas a notificação, não os bytes do arquivo, e pode criar um cartão duplicado.",
  "The consent card may have reached Teams. File delivery is not confirmed. Cancelling here does not remove any card already sent.": "O cartão de consentimento pode ter chegado ao Teams. A entrega do arquivo não foi confirmada. Cancelar aqui não remove nenhum cartão já enviado.",
  "The file may already exist in OneDrive. Cancelling stops this Paperclip transfer; it does not delete remote bytes. Uploads cannot be marked delivered or retried from this uncertain state.": "O arquivo pode já existir no OneDrive. Cancelar interrompe esta transferência do Paperclip, mas não exclui os bytes remotos. Os envios não podem ser marcados como entregues nem tentados novamente neste estado incerto.",
  "Paperclip lost confirmation after sending. Check the provider conversation first. Retrying can create a duplicate message.": "O Paperclip perdeu a confirmação após o envio. Verifique primeiro a conversa no provedor. Tentar novamente pode criar uma mensagem duplicada.",
  "Number copied": "Número copiado",
  "Shared Photon project · direct messages only. Enroll senders in Photon and link their Messages identities in Access. Groups cannot be enabled.": "Projeto Photon compartilhado · somente mensagens diretas. Cadastre os remetentes no Photon e vincule suas identidades do Messages em Acesso. Grupos não podem ser ativados.",
  "Enable each group individually. Agent replies are visible to everyone in that group; only authorized senders can start work.": "Ative cada grupo individualmente. As respostas do agente ficam visíveis para todos no grupo; somente remetentes autorizados podem iniciar trabalho.",
  "People must also enable Direct Messages in their shared Discord server’s Privacy Settings.": "As pessoas também precisam ativar Mensagens diretas nas Configurações de privacidade do servidor compartilhado do Discord.",
  "In channels, only respond to messages that @mention this bot, including thread replies. Direct messages never require an @mention and must be allowed above.": "Nos canais, responda apenas a mensagens que mencionem este bot com @, incluindo respostas em threads. Mensagens diretas nunca exigem @menção e devem ser permitidas acima.",
  "The bot may participate in group chats where it is installed.": "O bot pode participar de chats em grupo nos quais esteja instalado.",
  "Couldn’t update access": "Não foi possível atualizar o acesso",
  "Copy command": "Copiar comando",
  "Confirmation link copied": "Link de confirmação copiado",
  "People without linked accounts can start isolated tasks. They cannot approve actions, spend, or manage access. Requests are refused when isolation is unavailable.": "Pessoas sem contas vinculadas podem iniciar tarefas isoladas. Elas não podem aprovar ações, gastar ou gerenciar acesso. As solicitações são recusadas quando o isolamento está indisponível.",
  "Provider reply marked delivered": "Resposta do provedor marcada como entregue",
  "Provider reply retried": "Nova tentativa da resposta do provedor realizada",
  "Provider reply cancelled": "Resposta do provedor cancelada",
  "Slack callback URLs need an update. Save the current App Manifest, then exercise Events, Interactivity, and the registered command again.": "As URLs de callback do Slack precisam ser atualizadas. Salve o App Manifest atual e teste novamente Events, Interactivity e o comando registrado.",
  "Paperclip records each callback surface independently after Slack successfully calls it.": "O Paperclip registra cada superfície de callback de forma independente depois que o Slack a chama com sucesso.",
  "Not observed": "Não observado",
  "Finish setup": "Concluir configuração",
  "Resolve unconfirmed provider reply": "Resolver resposta do provedor não confirmada",
  "Paperclip lost confirmation after asking Slack to start the task. Check Slack first. Retrying can create a duplicate starter message and task.": "O Paperclip perdeu a confirmação após pedir ao Slack para iniciar a tarefa. Verifique o Slack primeiro. Tentar novamente pode criar uma mensagem inicial e uma tarefa duplicadas.",
  "Paperclip lost confirmation after sending this provider reply. Check the provider first. Marking it delivered applies any pending Paperclip state change; retrying can create a duplicate message.": "O Paperclip perdeu a confirmação após enviar esta resposta ao provedor. Verifique primeiro o provedor. Marcá-la como entregue aplica qualquer alteração pendente no Paperclip; tentar novamente pode criar uma mensagem duplicada.",
  "Cancel provider reply": "Cancelar resposta do provedor",
