  "Run tasks in this worktree": "Executar tarefas neste worktree",
  "This is an isolated git-worktree preview instance. Turn this on to let the scheduler execute runs here. Only tasks created after enabling will run automatically — copied/pre-existing tasks stay parked. Toggling off and on resets the cutoff.": "Esta é uma instância de visualização de git-worktree isolada. Ative para permitir que o agendador execute tarefas aqui. Somente tarefas criadas após a ativação serão executadas automaticamente — tarefas copiadas ou preexistentes permanecem estacionadas. Desativar e ativar novamente redefine o corte.",
  "This setting was armed in a different instance and copied here, so no tasks run automatically.": "Esta configuração foi ativada em outra instância e copiada para cá; portanto, nenhuma tarefa é executada automaticamente.",
  "This setting is missing its activation cutoff, so no tasks run automatically.": "Esta configuração não tem seu corte de ativação; portanto, nenhuma tarefa é executada automaticamente.",
  "Toggle it off and back on to arm execution for tasks created here.": "Desative e ative novamente para preparar a execução das tarefas criadas aqui.",
  "Show a \"Server\" section in the account drawer with the current server restart time and running commit.": "Mostrar uma seção \"Servidor\" no menu da conta com o horário atual de reinicialização do servidor e o commit em execução.",
  "Toggle server info debug view experimental setting": "Alternar configuração experimental de visualização das informações do servidor",
  "Add a \"Smoke Lab\" tab under Apps → Developer and an \"Integration smoke\" card on the dashboard for exercising every integration path against deterministic local fixtures (fake OAuth provider + loopback MCP servers). Private (non-public) deployments only.": "Adicionar uma aba \"Laboratório de smoke tests\" em Aplicativos → Desenvolvedor e um cartão \"Smoke de integrações\" no dashboard para exercitar cada caminho de integração com fixtures locais determinísticas (provedor OAuth falso + servidores MCP de loopback). Somente implantações privadas (não públicas).",
  "Toggle smoke lab experimental setting": "Alternar configuração experimental do laboratório de smoke tests",
  "Toggle task plan decomposition panel experimental setting": "Alternar configuração experimental do painel de decomposição do plano da tarefa",
  "Toggle classic task interface experimental setting": "Alternar configuração experimental da interface clássica de tarefas",
  "Toggle goals sidebar link experimental setting": "Alternar configuração experimental do link de objetivos na barra lateral",

