  "Creates a new provider-backed version. Consumers pinned to latest pick up the new value on the next run.": "Cria uma nova versão vinculada ao provedor. Os consumidores fixados na versão mais recente receberão o novo valor na próxima execução.",
  "Creates a new Paperclip metadata version that points at an existing provider secret. Paperclip does not write a new provider value.": "Cria uma nova versão de metadados do Paperclip que aponta para um segredo existente do provedor. O Paperclip não grava um novo valor no provedor.",
  "Writes a new version of the referenced provider secret. The new value becomes current for every consumer of that secret, in and outside Paperclip.": "Grava uma nova versão do segredo referenciado do provedor. O novo valor se torna atual para todos os consumidores desse segredo, dentro e fora do Paperclip.",
  "This does not delete the remote AWS Secrets Manager vault, secrets, or any AWS data.": "Isso não exclui o cofre remoto do AWS Secrets Manager, os segredos nem quaisquer dados da AWS.",
