  "Reconnect verifies this same Discord application and server installation. It does not add or remove the bot from the server. Leave fields blank to reuse saved credentials.": "Reconectar verifica este mesmo aplicativo do Discord e sua instalação no servidor. Isso não adiciona nem remove o bot do servidor. Deixe os campos em branco para reutilizar as credenciais salvas.",
  "Create one dedicated Discord application and bot for this Paperclip agent.": "Crie um aplicativo e bot dedicados do Discord para este agente do Paperclip.",
  "Reconnect verifies this same BotFather bot and automatically refreshes its Paperclip webhook and command menu. It does not recreate the bot or change its chat memberships. Leave the token blank to reuse the saved credential.": "Reconectar verifica o mesmo bot do BotFather e atualiza automaticamente o webhook do Paperclip e o menu de comandos. Isso não recria o bot nem altera sua participação em chats. Deixe o token em branco para reutilizar a credencial salva.",
  "Reconnect verifies this same Microsoft app, tenant, and bot identity. It does not upload or reinstall the Teams app. Leave fields blank to reuse saved credentials.": "Reconectar verifica este mesmo aplicativo da Microsoft, tenant e identidade do bot. Isso não envia nem reinstala o aplicativo do Teams. Deixe os campos em branco para reutilizar as credenciais salvas.",
  "Use your own Microsoft app credentials for this bot.": "Use suas próprias credenciais de aplicativo da Microsoft para este bot.",
  "Client secret value": "Valor do segredo do cliente",
  "Manifest settings copied": "Configurações do manifesto copiadas",
  "Copy manifest settings": "Copiar configurações do manifesto",
  "Paperclip webhook URL": "URL do webhook do Paperclip",
  "Regenerating immediately invalidates GitHub webhook signatures until you replace the secret in the GitHub App settings.": "Gerar novamente invalida imediatamente as assinaturas do webhook do GitHub até que você substitua o segredo nas configurações do aplicativo do GitHub.",
  "Generating another secret replaces the previous value. Paste the newest value into GitHub before continuing.": "Gerar outro segredo substitui o valor anterior. Cole o valor mais recente no GitHub antes de continuar.",
  "GitHub has verified this webhook.": "O GitHub verificou este webhook.",
  "Waiting for GitHub to deliver its signed webhook ping…": "Aguardando o GitHub entregar seu ping de webhook assinado…",
  "Finishing setup…": "Concluindo configuração…",
  "Didn’t work?": "Não funcionou?",
  "Manifest copied": "Manifesto copiado",
  "Copy manifest": "Copiar manifesto",
  "send a fresh message to your Photon number": "enviar uma nova mensagem para seu número Photon",
  "start a new issue or pull request conversation and mention the agent again": "iniciar uma nova conversa de issue ou pull request e mencionar o agente novamente",
  "start a new channel post and mention the agent again": "iniciar uma nova publicação no canal e mencionar o agente novamente",
  "send a new root mention to the agent": "enviar uma nova menção raiz ao agente",
  "Send one message to discover your phone number or Apple account address, then link that exact identity in Access. Send a fresh request after linking; earlier messages do not start work.": "Envie uma mensagem para descobrir seu número de telefone ou endereço da conta Apple e vincule essa identidade exata em Acesso. Envie uma nova solicitação após o vínculo; mensagens anteriores não iniciam trabalho.",
  "Identity readiness could not be checked": "Não foi possível verificar a prontidão da identidade",
  "Tap Start in Telegram to discover your account; the welcome does not start an agent run. Link the account privately in Access, then return and send the test message.": "Toque em Iniciar no Telegram para descobrir sua conta; a mensagem de boas-vindas não inicia uma execução do agente. Vincule a conta de forma privada em Acesso, volte e envie a mensagem de teste.",
  "Tap Start in Telegram to discover your account. Until linked, it is a restricted guest and still needs a sandbox-backed isolated run; test that path intentionally, or link it in Access and then send the test message.": "Toque em Iniciar no Telegram para descobrir sua conta. Até ser vinculada, ela é uma convidada restrita e ainda precisa de uma execução isolada apoiada por sandbox; teste esse caminho intencionalmente ou vincule-a em Acesso e envie a mensagem de teste.",
  "Unlinked identity detected": "Identidade não vinculada detectada",
  "you there?": "você está aí?",
  "In your Photon project, enroll your sender in Users and find its assigned number in Get started. Send a fresh message to that number from Apple Messages.": "No seu projeto Photon, cadastre o remetente em Usuários e encontre o número atribuído em Começar. Envie uma nova mensagem para esse número pelo Apple Messages.",
  "the dedicated number": "o número dedicado",
  "Link the discovered sender to a Paperclip person in Access, then send a fresh request.": "Vincule o remetente descoberto a uma pessoa do Paperclip em Acesso e envie uma nova solicitação.",
  "This Pro-compatible channel supports DMs only. Group messages cannot start work.": "Este canal compatível com Pro oferece suporte apenas a mensagens diretas. Mensagens em grupo não podem iniciar trabalho.",
  "For a group: add the number in Messages, send a message, enable the discovered group in Settings, then send a fresh request.": "Para um grupo: adicione o número no Messages, envie uma mensagem, ative o grupo descoberto em Configurações e envie uma nova solicitação.",
  "Tap Start.": "Toque em Iniciar.",
  "Send “Help me test this”.": "Envie “Ajude-me a testar isto”.",
  "Could not copy the number. Select it in the instructions below.": "Não foi possível copiar o número. Selecione-o nas instruções abaixo.",
  "Open your Slack DM": "Abrir sua mensagem direta do Slack",

