  "Paperclip archives the endpoint, stops new ingress, and retires its saved App key and webhook secret. It does not uninstall the GitHub App: the App, its installations, and its webhook settings remain until you remove or update them on GitHub.": "O Paperclip arquiva o endpoint, interrompe novas entradas e desativa a chave do aplicativo e o segredo do webhook salvos. Isso não desinstala o aplicativo do GitHub: o aplicativo, suas instalações e suas configurações de webhook permanecem até que você os remova ou atualize no GitHub.",
  "Paperclip archives the endpoint, stops its Paperclip Gateway connection, and retires its saved bot token. It does not uninstall the bot: the bot remains in the Discord server, and the application remains in the Developer Portal, until you remove them there.": "O Paperclip arquiva o endpoint, interrompe sua conexão com o Paperclip Gateway e desativa o token do bot salvo. Isso não desinstala o bot: ele permanece no servidor do Discord e o aplicativo permanece no Portal do desenvolvedor até que você os remova lá.",
  "Paperclip archives the endpoint, stops new ingress, and retires its saved client secret. It does not uninstall the Teams app: the Entra app registration, Azure Bot, custom Teams app, and Teams installations remain until you remove them in Microsoft.": "O Paperclip arquiva o endpoint, interrompe novas entradas e desativa o segredo do cliente salvo. Isso não desinstala o aplicativo do Teams: o registro do aplicativo Entra, o Azure Bot, o aplicativo personalizado do Teams e as instalações do Teams permanecem até que você os remova na Microsoft.",
  "Paperclip archives the endpoint and queues durable removal of its Telegram webhook and command menu. After Telegram confirms that cleanup, Paperclip retires the saved token. The BotFather bot and its chat memberships remain until you remove them in Telegram.": "O Paperclip arquiva o endpoint e coloca na fila a remoção durável do webhook e do menu de comandos do Telegram. Depois que o Telegram confirmar a limpeza, o Paperclip desativa o token salvo. O bot do BotFather e suas participações em chats permanecem até que você os remova no Telegram.",

