  "Agents cannot use this connection. Reconnect to restore access under the saved permission choices.": "Os agentes não podem usar esta conexão. Reconecte para restaurar o acesso conforme as permissões salvas.",
  "Refresh the catalog after changing tools in": "Atualize o catálogo depois de alterar as ferramentas em",
  "Refresh tools": "Atualizar ferramentas",
  "Your access choices and setup progress are kept with this connection.": "Suas escolhas de acesso e o progresso da configuração são mantidos com esta conexão.",
