  "Application type is inferred from the transport you choose next.": "O tipo de aplicativo é inferido a partir do transporte que você escolher em seguida.",
  "Only board-approved command templates can run. Arbitrary commands are never accepted.": "Somente modelos de comando aprovados pelo quadro podem ser executados. Comandos arbitrários nunca são aceitos.",
  "Free-text secrets are not accepted — pick a vault entry; Paperclip stores only the": "Segredos em texto livre não são aceitos — escolha uma entrada do cofre; o Paperclip armazena somente o",
