  "Reset Sessions": "Redefinir sessões",
  "Prompt template is replayed on every heartbeat. Keep it compact and dynamic to avoid recurring token cost and cache churn.": "O modelo de prompt é repetido a cada heartbeat. Mantenha-o compacto e dinâmico para evitar custo recorrente de tokens e alterações desnecessárias no cache.",
  "Bootstrap prompt is legacy and will be removed in a future release. Consider moving this content into the agent's prompt template or instructions file instead.": "O prompt de inicialização é legado e será removido em uma versão futura. Considere mover este conteúdo para o modelo de prompt do agente ou para o arquivo de instruções.",
  "Raw tracing is on for future runs. Paperclip keeps at most 64 MiB per run and automatically deletes it after 24 hours.": "O rastreamento bruto está ativado para execuções futuras. O Paperclip mantém no máximo 64 MiB por execução e o exclui automaticamente após 24 horas.",
