  "An earlier update has an unknown sender. Open Activity to check its delivery before starting a new update.": "Uma atualização anterior tem um remetente desconhecido. Abra Atividade para verificar a entrega antes de iniciar uma nova atualização.",
  "Saved delivery identity could not be read. Check Activity and restore browser storage before starting another send.": "Não foi possível ler a identidade de entrega salva. Verifique Atividade e restaure o armazenamento do navegador antes de iniciar outro envio.",
  "Your account changed. Reopen this task to send from your current account.": "Sua conta mudou. Reabra esta tarefa para enviar usando sua conta atual.",
  "The rejected send could not be saved. Restore browser storage, then retry this same request to recover its receipt.": "Não foi possível salvar o envio rejeitado. Restaure o armazenamento do navegador e tente novamente a mesma solicitação para recuperar o recibo.",
  "A selected file already belongs to another comment. Edit the rejected send to correct the selection.": "Um arquivo selecionado já pertence a outro comentário. Edite o envio rejeitado para corrigir a seleção.",
  "Selected task file (details unavailable)": "Arquivo selecionado da tarefa (detalhes indisponíveis)",
  "GitHub Apps cannot upload file bytes in comments. Checked files stay on the Paperclip task; GitHub receives an authenticated task link when this Board has a public URL, or a private-task notice otherwise.": "Os GitHub Apps não podem enviar bytes de arquivos em comentários. Os arquivos marcados permanecem na tarefa do Paperclip; o GitHub recebe um link autenticado da tarefa quando este Conselho tem uma URL pública ou, caso contrário, um aviso de tarefa privada.",
  "In personal Teams chats, recipients accept each file before upload. Channels and group chats receive supported images directly; other files stay on the task, with a task link or private-task notice.": "Em chats pessoais do Teams, os destinatários aceitam cada arquivo antes do envio. Canais e chats em grupo recebem imagens compatíveis diretamente; os demais arquivos permanecem na tarefa, com um link da tarefa ou um aviso de tarefa privada.",
  "These are the files selected for this send. Selection is locked until delivery is resolved.": "Estes são os arquivos selecionados para este envio. A seleção fica bloqueada até que a entrega seja resolvida.",
  "Only checked files will be published to the external conversation.": "Somente os arquivos marcados serão publicados na conversa externa.",
  "Saved delivery record could not be discarded. Restore browser storage, then try again.": "Não foi possível descartar o registro de entrega salvo. Restaure o armazenamento do navegador e tente novamente.",
  "Saved rejection could not be cleared. Restore browser storage before editing this send.": "Não foi possível limpar a rejeição salva. Restaure o armazenamento do navegador antes de editar este envio.",
  "Your exact draft and request identity are kept. Automatic resends stopped; choose Resend now to try again without creating a duplicate.": "Seu rascunho exato e a identidade da solicitação foram preservados. Os reenvios automáticos foram interrompidos; escolha Reenviar agora para tentar novamente sem criar uma duplicata.",
  "Your exact draft and request identity are kept. It resends on its own without creating a duplicate.": "Seu rascunho exato e a identidade da solicitação foram preservados. O envio será repetido automaticamente sem criar uma duplicata.",
  "Your exact draft and request identity are kept. Retry safely to learn the authoritative publication state without creating a duplicate.": "Seu rascunho exato e a identidade da solicitação foram preservados. Tente novamente com segurança para descobrir o estado oficial da publicação sem criar uma duplicata.",
  "Saved delivery identity could not be cleared. Restore browser storage before starting another send.": "Não foi possível limpar a identidade de entrega salva. Restaure o armazenamento do navegador antes de iniciar outro envio.",
  "Your message is posted to Slack with your name and starts the agent.": "Sua mensagem é publicada no Slack com seu nome e inicia o agente.",
  "Ordinary board comments remain Paperclip-only.": "Os comentários comuns do conselho continuam apenas no Paperclip.",
  "Missing delivery scope": "Escopo de entrega ausente",
  "Browser storage could not preserve this delivery identity. No update was sent. Restore browser storage, then reload to try again.": "O armazenamento do navegador não conseguiu preservar esta identidade de entrega. Nenhuma atualização foi enviada. Restaure o armazenamento do navegador e recarregue a página para tentar novamente.",
