  "Open the bot's private chat.": "Abra o chat privado do bot.",
  "Reconnect verifies this same App and installation, then updates its webhook URL, secret, and secure delivery settings. It does not reinstall the App or change repository access. Leave App ID and private key blank to reuse saved credentials. Keep Webhooks · Active enabled in GitHub; send a test conversation after reconnecting.": "Reconectar verifica este mesmo aplicativo e instalação e atualiza sua URL de webhook, segredo e configurações de entrega segura. Isso não reinstala o aplicativo nem altera o acesso aos repositórios. Deixe o ID do aplicativo e a chave privada em branco para reutilizar as credenciais salvas. Mantenha Webhooks · Ativo habilitado no GitHub e envie uma conversa de teste depois de reconectar.",
  "registers environment runtime settings there so the execution target stays instance-scoped while secret bindings still resolve through the selected organization context.": "registra as configurações de runtime do ambiente nesse local, mantendo o destino de execução no escopo da instância enquanto os vínculos de segredos continuam sendo resolvidos pelo contexto da organização selecionada.",
  "Start a setup sandbox, SSH in to customize the instance, then capture the running machine as a reusable image for future runs.": "Inicie um sandbox de configuração, acesse-o por SSH para personalizar a instância e capture a máquina em execução como uma imagem reutilizável para futuras execuções.",
