  "to Discord": "ao Discord",
  "In Discord Developer Portal, create an application. Copy its Application ID from General Information.": "No Portal do desenvolvedor do Discord, crie um aplicativo. Copie o ID do aplicativo em Informações gerais.",
  "Open Bot, create the bot, enable Message Content Intent, then reset and copy its token.": "Abra Bot, crie o bot, ative Message Content Intent, depois redefina e copie o token.",
  "Enable Developer Mode in Discord, right-click the target server, and copy its Server ID.": "Ative o Modo de desenvolvedor no Discord, clique com o botão direito no servidor de destino e copie o ID do servidor.",
  "Enter those values below, then use the generated install link to add the bot to that server.": "Insira os valores abaixo e use o link de instalação gerado para adicionar o bot a esse servidor.",
  "The install link grants only View Channels, Send Messages, Create Public Threads, Send Messages in Threads, Read Message History, Add Reactions, Embed Links, and Attach Files. Paperclip still requires each discovered channel to be enabled in Access.": "O link de instalação concede apenas Ver canais, Enviar mensagens, Criar threads públicas, Enviar mensagens em threads, Ler histórico de mensagens, Adicionar reações, Incorporar links e Anexar arquivos. O Paperclip ainda exige que cada canal descoberto seja habilitado em Acesso.",
  "or reply directly to a message from the bot.": "ou responda diretamente a uma mensagem do bot.",
  "to Microsoft Teams": "ao Microsoft Teams",
  "In Microsoft Entra, create a single-tenant app registration. Copy its Application (client) ID and Directory (tenant) ID, then create a client secret and copy its value.": "No Microsoft Entra, crie um registro de aplicativo de locatário único. Copie o ID do aplicativo (cliente) e o ID do diretório (locatário), depois crie um segredo do cliente e copie seu valor.",
  "In Azure, create an Azure Bot. Choose Single Tenant, use that Application ID, set its messaging endpoint to the Paperclip URL below, and add the Microsoft Teams channel.": "No Azure, crie um Azure Bot. Escolha Locatário único, use esse ID do aplicativo, defina o endpoint de mensagens como a URL do Paperclip abaixo e adicione o canal do Microsoft Teams.",
  "Use these exact portal sections and reuse the same Application ID in all three places.": "Use exatamente estas seções do portal e reutilize o mesmo ID do aplicativo nos três locais.",
  "This release supports personal chats, group chats, and standard team channels—not private channels.": "Esta versão oferece suporte a chats pessoais, chats em grupo e canais padrão de equipes — não a canais privados.",
  "Slack needs a public HTTPS URL to send messages to Paperclip. Configure one for this instance before creating or connecting your Slack app.": "O Slack precisa de uma URL HTTPS pública para enviar mensagens ao Paperclip. Configure uma para esta instância antes de criar ou conectar seu aplicativo do Slack.",
  "Open a channel and invite": "Abra um canal e convide",
  "I've sent the test message": "Enviei a mensagem de teste",
  Invite: "Convide",
  "to a channel to add it": "a um canal para adicioná-lo",
