  "will stop receiving new work from": "deixará de receber novos trabalhos de",
  ". Existing Paperclip tasks remain available.": ". As tarefas existentes do Paperclip continuam disponíveis.",
  "check from this App in your GitHub branch rules.": "verificação deste aplicativo nas regras de branch do GitHub.",
  "Included in every GitHub task. Type / to select a skill for the agent to use.": "Incluído em todas as tarefas do GitHub. Digite / para selecionar uma habilidade para o agente usar.",
  "Authorized people can always @mention this bot.": "Pessoas autorizadas sempre podem mencionar este bot com @.",
  "Reviews requested by @mention bypass these scheduling filters. Repository access and ignored files still apply.": "As revisões solicitadas por menção com @ ignoram estes filtros de agendamento. O acesso ao repositório e os arquivos ignorados continuam valendo.",
  "Optional formal decisions on GitHub. Scores, comments, and checks still work when these are off.": "Decisões formais opcionais no GitHub. Pontuações, comentários e verificações continuam funcionando quando isso está desativado.",
  "Choose who can mention this bot and whose activity can start work automatically.": "Escolha quem pode mencionar este bot e cuja atividade pode iniciar o trabalho automaticamente.",
  "Loading linked accounts…": "Carregando contas vinculadas…",
  "Automatic runs use the events and author filters in": "As execuções automáticas usam os eventos e filtros de autor em",
  "Automatic runs are off in": "As execuções automáticas estão desativadas em",
  "Allow specific GitHub users with a member as their sponsor. They receive restricted access, without company membership or the sponsor’s personal credentials.": "Permita usuários específicos do GitHub com um membro como patrocinador. Eles recebem acesso restrito, sem associação à empresa nem às credenciais pessoais do patrocinador.",
  "The member accountable for automatically created Paperclip tasks. GitHub authors remain recorded separately. This grants no access to the member’s personal credentials.": "O membro responsável pelas tarefas do Paperclip criadas automaticamente. Os autores do GitHub continuam registrados separadamente. Isso não concede acesso às credenciais pessoais do membro.",
  "Could not copy the link. Open account linking and copy the address.": "Não foi possível copiar o link. Abra a vinculação de contas e copie o endereço.",
  "Your existing connection still works. In": "Sua conexão existente continua funcionando. Em",
