    "Configure o espaço de trabalho concreto ao qual o Paperclip conecta este projeto. Esses valores controlam o comportamento de checkout por espaço de trabalho, os serviços de runtime padrão para espaços de execução filhos e permitem substituir comandos de configuração ou limpeza quando um espaço precisa de tratamento especial.",
  Search: "Pesquisar",
  "wrap a phrase in quotes to match the exact sequence.": "coloque uma frase entre aspas para corresponder à sequência exata.",
  "reopens the command palette pre-seeded with your current query.": "reabre a paleta de comandos pré-preenchida com sua consulta atual.",
  "Your input and filters are still here, so you can retry or fall back to the Tasks filter.": "Sua entrada e seus filtros continuam aqui, então você pode tentar novamente ou voltar ao filtro Tarefas.",
