  "Install in Slack": "Instalar no Slack",
  "Paperclip creates a fresh one-hour runtime token when an agent run starts, then revokes it when the run ends. Codex can receive the same gateway through both an app connection and the managed-gateway path, so one run may leave two revoked rows. These are audit history, not repeated manual tokens.":
    "O Paperclip cria um novo token de runtime com duração de uma hora quando uma execução de agente começa e o revoga quando a execução termina. O Codex pode receber o mesmo gateway por uma conexão de aplicativo e pelo caminho de gateway gerenciado, então uma execução pode deixar duas linhas revogadas. Isso é histórico de auditoria, não tokens manuais repetidos.",
