  "Every component, style, and pattern used across Paperclip.": "Todos os componentes, estilos e padrões usados no Paperclip.",
  "This page should be updated when new UI primitives or app-level patterns ship.":
    "Esta página deve ser atualizada quando novos primitivos de UI ou padrões de aplicativo forem lançados.",
  "CollectionToolbar owns shared geometry while each page owns its state and behavior. The canonical task row is opt-in during migration: status leads, unread work uses title emphasis, metadata remains stable, and the task identifier trails.":
    "O CollectionToolbar controla a geometria compartilhada enquanto cada página controla seu estado e comportamento. A linha canônica de tarefa é opcional durante a migração: o status vem primeiro, o trabalho não lido usa ênfase no título, os metadados permanecem estáveis e o identificador da tarefa fica no final.",
