  "Used wherever a task is referenced — in markdown, the Related Work tab, and activity summaries. Pass":
    "Usado sempre que uma tarefa é referenciada — em markdown, na aba Trabalho relacionado e nos resumos de atividade. Passe",
  "to show the target issue's state at a glance. Use": "para mostrar o estado da tarefa de destino rapidamente. Use",
  "for compact badges with direct navigation. Pass": "para badges compactos com navegação direta. Passe",
  "for a separate blocker removal control with reserved space. Use": "para um controle separado de remoção de bloqueador com espaço reservado. Use",
  "for \"removed\" contexts.": "para contextos de \"removido\".",
  "Existence-only reference to a private task shown from a surface the viewer can see (a blocker edge, a mention). Mono id + lock, dashed muted border,":
    "Referência somente de existência a uma tarefa privada exibida em uma superfície que o visualizador pode ver (uma borda de bloqueador, uma menção). ID monoespaçado + cadeado, borda tracejada discreta,",
  "no title, never a link": "sem título, nunca um link",
  ". Falls back to &quot;Private&quot; when even the identifier is withheld.": ". Usa &quot;Privado&quot; quando até o identificador é ocultado.",
  "The brand &quot;capsule is the agent&quot; motif. A single agent reads as a tall pill that moves through three states as it comes to life. The online fill uses the live brand agent-gradient tokens (":
    "O motivo de marca &quot;a cápsula é o agente&quot;. Um único agente aparece como uma cápsula alta que passa por três estados ao ganhar vida. O preenchimento online usa os tokens ativos de gradiente do agente da marca (",
  "skips the liquid rise and pulses and renders the final state.": "ignora a subida líquida e as pulsações e renderiza o estado final.",
  "online · blue glow": "online · brilho azul",
