  "Description (multiline, auto-sizing)": "Descrição (várias linhas, dimensionamento automático)",
  "Native single-value dropdowns share an inset, theme-aware caret and reserve room for it in the base stylesheet. Multiple-selection lists and controls with a custom icon keep their own appearance.":
    "Os menus suspensos nativos de valor único compartilham um indicador interno sensível ao tema e reservam espaço para ele na folha de estilos base. Listas de seleção múltipla e controles com ícone personalizado mantêm sua própria aparência.",
