  "Issue List": "Lista de tarefas",
  "The dashboard and Live runs page use the same compact cards. In-progress task icons animate across the app, including between runs, to represent task workflow status. Live indicators report active execution. Open a run to view its status and transcript.":
    "O painel e a página de execuções ao vivo usam os mesmos cards compactos. Os ícones de tarefas em andamento são animados pelo aplicativo, inclusive entre execuções, para representar o status do fluxo da tarefa. Os indicadores ao vivo informam a execução ativa. Abra uma execução para ver seu status e sua transcrição.",
  "Card Title": "Título do card",
  "Card description with supporting text.": "Descrição do card com texto de apoio.",
  "Card content goes here. This is the main body area.": "O conteúdo do card fica aqui. Esta é a área principal do corpo.",
