  "This is a sample dialog showing the standard layout with header, content, and footer.":
    "Este é um diálogo de exemplo que mostra o layout padrão com cabeçalho, conteúdo e rodapé.",
  "Agent Alpha": "Agente Alpha",
  "Shared by connection setup and trigger previews. Setup navigation takes over the section sidebar; each step owns a single footer.":
    "Compartilhado pela configuração de conexões e visualizações de gatilhos. A navegação da configuração assume a barra lateral da seção; cada etapa tem um único rodapé.",
  List: "Lista",
  "Comments (2)": "Comentários (2)",
  "Started working on the authentication module. Will need API keys configured.":
    "Comecei a trabalhar no módulo de autenticação. Será necessário configurar as chaves de API.",
  "API keys have been added to the vault. Please proceed.": "As chaves de API foram adicionadas ao cofre. Prossiga.",
