  "Persistent at the top of the Tools & Access surface. Tints to": "Persistente no topo da superfície Ferramentas e acesso. Fica colorido quando",
  "when governed tool calls were denied or failed in the last hour. Observability only — enforcement lives in the tool gateway.":
    "quando chamadas de ferramentas governadas foram negadas ou falharam na última hora. Apenas observabilidade — a aplicação vive no gateway de ferramentas.",
  "Preview invitation modal": "Visualização do modal de convite",
